# Manually use parsed rows above excluding missing prostate for swap depth diagnostics
import numpy as np
rows=[('Bladder',7361379926,701506327),('Brain',12048619808,1168148790),('Cloaca',4079467003,484000505),('GallBladder',4980611273,565994637),('Gill',11566811496,1094125058),('Heart',9197722750,868549497),('Intestine',6322122007,699794434),('Kidney',7755800716,745602917),('Limb',11646072827,1147926115),('Liver',3644606637,398317869),('Lung',9346073087,877686879),('Pancreas',12518564809,1398702406),('Spleen',5192026012,497829833),('Stomach',4355106294,455786546)]
names=[r[0] for r in rows]; sizes=np.array([r[1] for r in rows],float); libs=np.array([r[2] for r in rows],float)
def corr(a,b): return np.corrcoef(a,b)[0,1]
def cv_ratio(l):
    rat=l/sizes
    return rat.std()/rat.mean()
print('noswap corr',corr(sizes,libs),'cv',cv_ratio(libs))
best=[]
for i in range(len(names)):
 for j in range(i+1,len(names)):
    l=libs.copy(); l[i],l[j]=l[j],l[i]
    best.append((corr(sizes,l),-cv_ratio(l),names[i],names[j],l[i]/sizes[i],l[j]/sizes[j]))
print('top corr')
for c,negcv,a,b,ra,rb in sorted(best,reverse=True)[:15]: print(f'{c:.6f} cv={-negcv:.4f} {a},{b} ratios_after={ra:.4f},{rb:.4f}')
print('top cv')
for c,negcv,a,b,ra,rb in sorted(best,key=lambda x:x[1],reverse=True)[:15]: print(f'{c:.6f} cv={-negcv:.4f} {a},{b} ratios_after={ra:.4f},{rb:.4f}')
PY"
